# content_infect.py — analysis/manuscript script for the study of care for infectious and parasitic diseases across Korean districts, 2011-2024.
#  Infectious Diseases 규칙: Research Article, 구조화 초록 250(Background/Objectives/Methods/Results/Conclusion), 키워드 5-7, 단어 제한 없음, 단일 익명, 형식 자유.
#  공변량 세트는 공변량 모형 적합 전 고정(종속변수 역학 풀, 6-B 해당 없음). 결과 열람 뒤 추가한 것(위도·기온 상관 기술)은 Methods에 그 사실을 적는다.
from numbers_infect import load, ROB, REV, RS
import os, pandas as pd
N = load()
def fb(x): return f"{x:.3f}"   # 결과 CSV가 3자리 반올림 → 1.000 경계는 반올림 전 값으로 판정했다고 Methods·표 각주에 명시
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {fb(t[1])} to {fb(t[2])}"
def ci(v): r = N["main"][v]; return tci((r["IRR"], r["lo"], r["hi"]))
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["s41"][("H1_nco_" + o, v)]
S41 = lambda a, v: N["s41"][(a, v)]
SC = lambda s, v: N["sens_main"][s][v]
REG = lambda v, r: N["s50_region"][(v, r)]
EN = {"강원도": "Gangwon", "충청남도": "South Chungcheong", "충청북도": "North Chungcheong", "경기도": "Gyeonggi", "서울시": "Seoul", "경상북도": "North Gyeongsang",
      "경상남도": "South Gyeongsang", "전라남도": "South Jeolla", "전라북도": "North Jeolla", "광주시": "Gwangju", "부산시": "Busan", "인천시": "Incheon", "울산시": "Ulsan",
      "대전시": "Daejeon", "세종시": "Sejong", "대구시": "Daegu", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + ", and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
DM, OB, SMK, LTC, BL, SPH, TMP, BATH, POOL, SCR, WALK, MPA, PSF = (
    "screening_suspected_diabetes_share", "screening_normalB_obesity_share", "current_smoking_rate", "long_term_care_hospitals_per_100k", "basic_livelihood_rate",
    "single_person_household_share", "annual_mean_temperature", "public_baths_per_10k", "public_pools_per_100k", "screening_uptake", "walking_practice_rate",
    "moderate_pa_rate", "public_sports_facilities_per_100k")
TITLE = "A south-north divide in care for infectious and parasitic diseases held across Korean districts for fourteen years"
KEYWORDS = "Small-area variation; Spatiotemporal persistence; Health care utilization; Communicable diseases; Bayesian disease mapping; Republic of Korea"
assert ":" not in TITLE and "2011" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and "unexplain" not in TITLE and "unaccounted" not in TITLE and len(TITLE.split()) <= 22
assert 4 <= len(KEYWORDS.split(";")) <= 6   # ASAP 4-6
_LK = pd.read_csv(os.path.join(RS, "S1_likelihood.csv")); _LK = _LK[_LK.set == "REF_forced_only"].set_index("family").WAIC
_FAM = pd.read_csv(os.path.join(RS, "S3_main_fit.csv")).family.iloc[0]
assert _FAM == "nbinomial" and _LK["nbinomial"] < _LK["poisson"] and abs(_LK["nbinomial"] - N["waic_forced"]) < 0.15
NHYP = N["n_hyp"]; EXP_CHANCE = 0.05 * NHYP; assert NHYP == 13
SUP = {"composition": "Online Resource 1 (Table S1)", "methods": "Online Resource 1 (Appendix A)", "covariates": "Online Resource 1 (Table S2)", "datacheck": "Online Resource 1 (Table S3)",
       "specs": "Online Resource 1 (Table S4)", "regions": "Online Resource 1 (Table S5)", "persistence": "Online Resource 1 (Fig. S1)"}   # Springer: Online Resource 표기, 첫 인용 순서
def sup(k): return SUP[k]
WN = ("W1_2011-15", "W2_2016-19", "W3_2020-24")
_W = pd.read_csv(os.path.join(RS, "S4_window_IRR.csv")).set_index(["cov", "window"])
def wt(v, w): r = _W.loc[(v, w)]; return (r.IRR, r.lo, r.hi, bool(r.cred))
RET = N["ret14"]; NALT = RET[BL][1]; assert NALT == 14
BW = lambda v, part: N["bw"][f"{v}__{part}"]
_hot = N["type_class"]["hotspot"]; _nt = N["n_type"]; _cold = N["type_class"]["coldspot"]
_NC = lambda v: tci((N["negctl"][v]["IRR"], N["negctl"][v]["lo"], N["negctl"][v]["hi"]))
VP = N["varpart"]; vp = lambda k: 100 * VP[k]["share_of_linear_predictor_var"]
CP = N["comp"]; _r = lambda lab: (CP.loc[lab].iloc[:10].astype(float).min(), CP.loc[lab].iloc[:10].astype(float).max())
C_INT = _r("1+1a Intestinal infections incl. A09 (A00-A09)"); C_A09 = _r("1a Gastroenteritis and colitis of infectious and unspecified origin (A09)")
C_MYC = _r("6 Mycoses (B35-B49)"); C_HSV = _r("3a Herpes simplex (B00)"); C_ZOS = _r("3b Zoster (B02)"); C_WRT = _r("3c Viral warts (B07)")
C_HEP = _r("4 Viral hepatitis (B15-B19)"); C_STI = _r("5 Predominantly sexually transmitted infections (A50-A64)"); C_TB = _r("2 Tuberculosis (A15-A19)")
C_SCA = _r("7 Pediculosis, acariasis and other infestations (B85-B89)")
R1 = lambda a: f"{a[0]:.1f}%-{a[1]:.1f}%"
SR = N["screen_row"]
KHII, KHIV, KHI = (N["s43_waic"][k] for k in ("KH_typeII", "KH_typeIV", "KH_typeI"))
_MT = pd.read_csv(os.path.join(os.path.dirname(os.path.dirname(RS)), 'INFECT', 'panel_META_INFECT_std3.csv'), encoding='utf-8-sig').set_index('variable')
_IMP_SPH = int(_MT.loc['single_person_household_share', ['n_imputed_interp', 'n_imputed_sgg_mean', 'n_imputed_year_mean']].sum())
NOT_H = [v for v in (DM, OB, LTC, SPH, TMP, BATH, WALK, MPA)]

METHODS = [
("Design, outcome, and population",
 f"This ecological study used annual numbers of people treated for infectious and parasitic diseases (International Classification of Diseases, 10th revision, Chapter I, A00-B99, as the principal diagnosis) in 2011-2024 from the Regional Medical Care Utilization Statistics of the National Health Insurance Service [@web:nhis2026regional], which count each person once a year by district of residence and include inpatient and outpatient care. The outcome is therefore care for the whole chapter, not the incidence of any single infection: a count of unique people with at least one such claim, reflecting both disease and the decision to seek care [@andersen2008national]. Earlier units were aggregated to {N['n_districts']} districts with 2024 boundaries ({N['n_rows']:,} district-years), with mid-year resident populations by sex and 5-year age group as denominators [@web:mois2026population] ({sup('methods')}). Because district tables give the chapter total only, its composition was described from national counts by three-character code for 2015-2024 from the National Health Insurance Service big data platform [@web:nhis2026disease]; a person treated under two codes is counted under both, so shares refer to summed code-level counts ({sup('composition')})."),
("Sex and age standardization",
 "Expected counts were obtained by indirect standardization for sex and age. National treatment counts in ten age groups (0-9 to 50-59 years in 10-year groups, 60-64 to 70-74 years in 5-year groups, and 75 years or older, the finest grouping published in every year) were split by sex using the male share of summed three-character counts in each age group and year (2015 shares for 2011-2014), applied to each district's population by sex and age, and rescaled each year to the national total [@inskip1983methods]. Observed over expected counts gives the standardized treatment ratio (STR). National trends were directly standardized to the 2015 population by sex and age after rescaling the national rates to the annual sum of district counts."),
("District characteristics",
 f"Thirteen district characteristics with an expected direction were selected from the literature on infections of the skin and mucosa, reactivated infections, and care use, and fixed before any covariate model was fitted. Host susceptibility was represented by the shares of general health screening attendees classified as having suspected diabetes and as needing obesity management, because diabetes and obesity raise the risk of zoster, candidiasis, and dermatophytosis [@muller2005increased; @carey2018risk; @huang2022association; @falagas2006obesity; @shahabudin2024candida], by the age-standardized current smoking rate from the Community Health Survey [@kang2015korea; @arcavi2004cigarette], and by long-term care hospitals per 100,000 population, settings with outbreaks of scabies among older residents [@utsumi2010types; @lee2021previous]. Socioeconomic position was represented by the basic livelihood security recipient rate [@semenza2010strategies; @baker2012increasing] and the share of single-person households, an indirect marker of living arrangements whose link with infection is uncertain: loneliness but not social isolation was associated with hospital-treated infection in one cohort [@elovainio2023association]. Environmental exposure was represented by indirect proxies: annual mean temperature, interpolated from weather stations, because warm conditions favor some skin infections and hot days increase outpatient visits for skin disease [@kaffenberger2017effect; @huang2022heat], and public bathhouses per 10,000 and public swimming pools per 100,000 population, because dermatophytes have been recovered from their floors and swimming is a secondary risk factor for warts [@kamihama1997tinea; @ekowati2018potential; @montynlucher2025systematic]. Care-seeking was represented by uptake of the general health screening [@andersen2008national]. Physical activity, which has been associated with lower risk of community-acquired infection [@chastin2021effects; @nieman2019compelling], was represented by walking and moderate-or-vigorous activity from the same survey and by public sports facilities per 100,000 population. Exposures through food and water were outside the scope of this study and were not included. Five controls were forced into every model: urban population share, physician density, sex ratio, fiscal autonomy, and the share aged 80 years or older, because the oldest standardization group cannot capture differences in very old age. For 2021-2023, the published basic livelihood rate of 11 cities with administrative wards was implausibly low, below 20% of the same city's 2020 and 2024 average, so these 33 district-years were treated as missing and replaced by within-district linear interpolation. All covariates were standardized to 1 standard deviation (SD); missing years were interpolated within districts, and years before the first observation, such as single-person households before 2015, were filled with district means ({sup('covariates')}); panel checks before modeling are summarized in {sup('datacheck')}. Annual precipitation was considered but not used because station gaps produced implausible values."),
("Statistical analysis",
 f"The likelihood (Poisson or negative binomial) was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model. Models had an offset of log expected counts, a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@besag1991bayesian; @riebler2016intuitive; @simpson2017penalising], and first-order random-walk and independent year effects, fitted by integrated nested Laplace approximation [@rue2009approximate] in R [@web:rcore2026]; island districts were linked to their nearest mainland neighbors (593 edges), and all priors are listed in {sup('methods')}. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1, judged from unrounded values, so an interval shown with a bound of 1.000 may be credible. Intervals were not adjusted for multiplicity; with {NHYP} characteristics, about {EXP_CHANCE:.2f} intervals would exclude 1 by chance if all associations were null and intervals behaved like frequentist intervals, so the findings are exploratory. In a covariate-subset analysis adapted from multiverse analysis [@steegen2016increasing], 200 random subsets of the characteristics were fitted with all forced controls; a characteristic was subset-stable if its CrI excluded 1 in at least 75% of the subsets containing it with the same sign in at least 95%. The variance of the posterior mean of each linear predictor component (covariates, structured and unstructured district effects, and year effects) was expressed as a share of the variance of the total linear predictor; shares need not sum to 100% because components covary. Residual hot and cold spots had a posterior probability of a residual spatial RR above 1 greater than 0.95 or less than 0.05, for the full period and three windows (2011-2015, 2016-2019, 2020-2024). Moran's I was computed for annual and 14-year pooled log STRs [@moran1950notes], persistence by Kendall's W of annual rankings, and emerging hot spot analysis combined the yearly Getis-Ord Gi* statistic [@getis1992analysis; @ord1995local] with a Mann-Kendall trend test of its z-scores [@mann1945nonparametric]."),
("Sensitivity analyses",
 f"Knorr-Held type I-IV space-time interactions were added [@knorrheld2000bayesian]; type I adds independent district-year effects, type II district-specific random-walk trends, type III year-specific spatial patterns, and type IV trends structured in space and time. Because type I effects act as observation-level effects, its WAIC was not compared with that of the other models. Subset-stable characteristics were decomposed into district means and two-way-centered within-district deviations [@bell2015explaining], and the principal model was refitted in each window. Fourteen alternative specifications varied the likelihood, time effects (including province-by-year random effects), smoothing of a forced control, a Spatial+-type adjustment for spatial confounding [@dupont2022spatial; @hodges2010adding], 1- and 2-year lags, extreme values, survey averaging, and the years included; further checks varied priors and neighborhoods, left out each province or year, perturbed filled values 20 times with normal noise scaled to the within-district SD and pooled the fits with Rubin's rules, and added a post-2020 interaction, out-of-district outpatient care, and region-specific slopes for five regions ({sup('specs')}). Expected counts were also recomputed by age only, in eight coarser age groups, and without the 80 years or older control. People treated for arthritis (M00-M19 and M22-M25) and for stomach cancer (C16), from the same statistics and standardized in the same way, served as comparison outcomes sharing care-seeking and socioeconomic determinants but not infection; the principal model was refitted to each. Cardiopulmonary resuscitation awareness, the road pavement rate, and fires per 10,000 residents served as negative-control exposures and were added one at a time to the principal model [@lipsitch2010negative]. E-values quantified the confounding needed to explain associations [@vanderweele2017sensitivity]; posterior predictive checks, including prediction of held-out 2024 counts conditional on the 2024 expected counts and covariates, assessed fit; because expected counts are rescaled to each year's national total, the held-out check assesses the distribution of counts among districts rather than the national level. Residual Moran's I was tested by permutation for positive autocorrelation."),
("Analyses added after results were seen",
 "Because the residual map followed a south-north pattern, Spearman correlations of district residual RRs and of covariate-free empirical Bayes smoothed STRs with the latitude of district centroids, and of smoothed STRs with district mean temperature and other characteristics, were computed as descriptive statistics. Two characteristics were credible opposite to the expected direction; they were examined with the decomposition, space-time, province-by-year, window, and region-specific results listed above. These analyses were not part of the original plan."),
("Ethics and reporting",
 "The Institutional Review Board of Hongik University approved the study on November 4, 2025 (7002340-202511-HR-012) and its continuing review on November 3, 2026 (7002340-202611-HR-040), and waived informed consent because only published aggregate statistics were used. District tables are not published by sex or by diagnostic code, so sex- and code-specific district analyses were not possible. Reporting follows the STROBE statement [@vonelm2007strengthening] and its RECORD extension for routinely collected health data [@benchimol2015reporting] (Online Resource 1, Appendix B)."),
]

RESULTS = [
("Treated people, composition, and trends",
 f"Over 2011-2024, {N['cases_total']:,} treated person-years (people treated in a year, summed over years) were recorded in {N['py']/1e6:.0f} million person-years of population, or about one person in five each year (Table 1). The number treated was {N['cases_2011']:,} in 2011 and {N['cases_2024']:,} in 2024; the directly sex- and age-standardized rate was {N['asr_2011']:,.0f} per 100,000 in 2011, {N['asr_2019']:,.0f} in 2019, {N['asr_2020']:,.0f} in 2020, and {N['asr_2024']:,.0f} in 2024 (Fig. 1b). In the national three-character counts for 2015-2024, intestinal infections (A00-A09) accounted for {R1(C_INT)} of summed code-level counts, including {R1(C_A09)} for gastroenteritis and colitis of infectious and unspecified origin (A09); mycoses (B35-B49) for {R1(C_MYC)}; herpes simplex (B00) for {R1(C_HSV)}; zoster (B02) for {R1(C_ZOS)}; viral warts (B07) for {R1(C_WRT)}; viral hepatitis (B15-B19) for {R1(C_HEP)}; infections with a predominantly sexual mode of transmission (A50-A64) for {R1(C_STI)}; tuberculosis (A15-A19) for {R1(C_TB)}; and pediculosis, scabies, and other infestations (B85-B89) for {R1(C_SCA)} ({sup('composition')})."),
("Geography",
 f"Moran's I was {N['moran_pooled']:.2f} for pooled log STRs and {N['moran_year_min']:.2f}-{N['moran_year_max']:.2f} annually. Kendall's W for district rankings was {N['kendall_W']:.2f} across the 14 years and {N['kendall_W_1119']:.2f} and {N['kendall_W_2024']:.2f} in 2011-2019 and 2020-2024. In the principal model, structured district effects accounted for {vp('spatial_structured'):.1f}% of the variance of the linear predictor, unstructured district effects for {vp('spatial_unstructured'):.1f}%, the {NHYP} characteristics for {vp('fixed_hypothesis'):.1f}%, the forced controls for {vp('fixed_forced_controls'):.1f}%, and year effects for {vp('year_effects'):.1f}%; the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f} to {N['phi'][2]:.2f}). After adjustment, {N['n_hot']} districts were residual hot spots ({N['hot_all_windows']} in all three windows), mainly in {sidos(N['hot_by_sido'], 4)}, comprising {_hot['county']} of {_nt['county']} counties, {_hot['city']} of {_nt['city']} cities, and {_hot['ward']} of {_nt['ward']} urban wards; {N['n_cold']} were cold spots ({N['cold_all_windows']} in all windows), mainly in {sidos(N['cold_by_sido'], 4)} (Fig. 1a; {sup('persistence')}). Residual spatial RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}. Emerging hot spot analysis classified {N['ehsa']['Persistent hot']} districts as persistent hot spots, all in Gwangju and the two Jeolla provinces, and {N['ehsa']['Persistent cold'] + N['ehsa']['Intensifying cold']} as persistent or intensifying cold spots, all in Gangwon and the northern parts of North Chungcheong and North Gyeongsang. In the post hoc descriptive analysis, the residual RR correlated with centroid latitude at {N['lat_rr']:.2f} (Spearman) and the covariate-free smoothed STR at {N['lat_eb']:.2f}; the smoothed STR correlated with mean temperature at {N['eb_tmp']:.2f}, with suspected diabetes at {N['eb_dm']:.2f}, with screening uptake at {N['eb_scr']:.2f}, and with the current smoking rate at {N['eb_smk']:.2f}."),
("District characteristics",
 f"Adding the {NHYP} characteristics lowered WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}. Standardized treatment ratios were lower where public sports facility density was higher ({ci(PSF)}) and higher where screening uptake ({ci(SCR)}) and public swimming pool density ({ci(POOL)}) were higher (Table 2, Fig. 2). Two characteristics were credibly associated in the direction opposite to that expected: the basic livelihood rate ({ci(BL)}) and current smoking ({ci(SMK)}). Suspected diabetes ({ci(DM)}), obesity ({ci(OB)}), long-term care hospitals ({ci(LTC)}), single-person households ({ci(SPH)}), temperature ({ci(TMP)}), public bathhouses ({ci(BATH)}), walking ({ci(WALK)}), and moderate-or-vigorous activity ({ci(MPA)}) were not credibly associated. Two of the three negative-control exposures were credibly associated (road pavement, {_NC('road_pavement_rate')}; fires, {_NC('fires_per_10000')}; resuscitation awareness, {_NC('cpr_awareness_rate')})."),
("Robustness",
 f"Public sports facilities, screening uptake, the basic livelihood rate, and smoking were subset-stable (credible in {100*N['mv'][PSF]['cred_frac']:.0f}%, {100*N['mv'][SCR]['cred_frac']:.0f}%, {100*N['mv'][BL]['cred_frac']:.0f}%, and {100*N['mv'][SMK]['cred_frac']:.0f}% of the subset fits containing them); swimming pools ({100*N['mv'][POOL]['cred_frac']:.0f}%) and single-person households ({100*N['mv'][SPH]['cred_frac']:.0f}%) were not. The four subset-stable characteristics remained credible in {RET[PSF][0]}, {RET[SCR][0]}, {RET[BL][0]}, and {RET[SMK][0]} of the {NALT} alternative specifications in {sup('specs')}, after recomputing expected counts by age only ({tci(SC('sage', PSF))} for sports facilities), and in the type I space-time model. In the type II and IV models, which allow district-specific time trends and lowered WAIC by {abs(KHII - N['waic_main']):,.0f} and {abs(KHIV - N['waic_main']):,.0f}, none of the four was credible (sports facilities {tci(S43('KH_typeIV', PSF))} in type IV); in the type III model, whose WAIC was higher than that of the principal model, the basic livelihood rate and sports facilities remained credible. In the window refits (2011-2015, 2016-2019, and 2020-2024), none of the four was credible except screening uptake in 2020-2024 ({tci(wt(SCR, WN[2]))}). Single-person households, not credible in the principal model, were credible below 1 in the type II-IV models ({tci(S43('KH_typeIV', SPH))} in type IV), and swimming pools were credible above 1 in the type III and IV models ({tci(S43('KH_typeIV', POOL))} in type IV). Single-person households were filled with district means in {_IMP_SPH:,} district-years, mostly before 2015; pooled over 20 perturbations of filled values, their rate ratio was {N['rubin'][SPH]['IRR_pooled']:.3f} (95% CrI {N['rubin'][SPH]['lo']:.3f} to {N['rubin'][SPH]['hi']:.3f}). With province-by-year effects, sports facilities ({tci(S41('C4_sido_year_iid', PSF))}) and the basic livelihood rate remained credible, but screening uptake and smoking did not. For sports facilities, the within-district component was below 1 ({tci(BW(PSF, 'within'))}) and the between-district component above 1 ({tci(BW(PSF, 'between'))}); credible intervals of region-specific slopes were below 1 in all five regions ({sup('regions')}). Screening uptake was credible between ({tci(BW(SCR, 'between'))}) and within districts ({tci(BW(SCR, 'within'))}), but its region-specific slope was below 1 in Honam ({tci(REG(SCR, 'Honam'))}), and was also credible above 1 for stomach cancer ({tci(NCO('GCA', SCR))}) and arthritis ({tci(NCO('ARTH', SCR))}). For the comparison outcomes, sports facilities were credible above 1 for stomach cancer ({tci(NCO('GCA', PSF))}) and not credible for arthritis. E-values for the point estimates were {N['evalue'][PSF]['E_point']:.2f} for sports facilities, {N['evalue'][SCR]['E_point']:.2f} for screening uptake, {N['evalue'][BL]['E_point']:.2f} for the basic livelihood rate, and {N['evalue'][SMK]['E_point']:.2f} for smoking."),
("Associations opposite to the expected direction",
 f"For the basic livelihood rate, the within-district estimate excluded 1 ({tci(BW(BL, 'within'))}) whereas the between-district estimate did not ({tci(BW(BL, 'between'))}); it was credible with province-by-year effects ({tci(S41('C4_sido_year_iid', BL))}) but not in the type II or IV models or any window, and credible intervals of region-specific slopes were entirely below 1 in four of five regions ({sup('regions')}). For the comparison outcomes it was credible above 1 for arthritis ({tci(NCO('ARTH', BL))}) and stomach cancer ({tci(NCO('GCA', BL))}). For smoking, neither the within-district ({tci(BW(SMK, 'within'))}) nor the between-district estimate ({tci(BW(SMK, 'between'))}) was credible; the estimate was not credible with province-by-year effects ({tci(S41('C4_sido_year_iid', SMK))}), in the type II or IV models, in any window, or for either comparison outcome, and region-specific slopes were credible only in the capital region ({tci(REG(SMK, 'Capital'))})."),
("Model fit",
 f"Residual Moran's I was {N['moran_resid']:.3f}, with no positive residual autocorrelation (one-sided permutation P = {N['moran_resid_p']:.3f}). Posterior predictive 95% intervals covered {100*N['ppc']['coverage95']:.1f}% of district-years and {100*N['oos']['coverage95']:.1f}% of held-out 2024 district counts (median absolute error {N['oos']['median_abs_pct_error']:.1f}%), and the probability integral transform departed from uniformity (Kolmogorov-Smirnov P < 0.001). A post-2020 main effect was not credible ({tci(N['covid_main'])}), and {N['covid_nint']} of the {NHYP} characteristics had credible post-2020 interactions ({sup('specs')})."),
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
_E = pd.read_csv(os.path.join(RS, "S11_ehsa.csv"))
assert _E[_E.EHSA == "Persistent hot"].fbd_region.str.match(r"^(광주시|전라남도|전라북도)").all()
assert _E[_E.EHSA.isin(["Persistent cold", "Intensifying cold"])].fbd_region.str.match(r"^(강원도|충청북도(단양군|충주시|괴산군|제천시)|경상북도(영주시|문경시|예천군|봉화군|안동시))").all()
H = [v for v in M if M[v]["role"] == "hypothesis"]
assert set(ROB) == {SMK, BL, SCR, PSF} and N["waic_main"] < N["waic_forced"]
assert {v for v in H if M[v]["cred"]} == {SMK, BL, POOL, SCR, PSF} and M[PSF]["IRR"] < 1 and M[SCR]["IRR"] > 1 and M[POOL]["IRR"] > 1 and M[BL]["IRR"] < 1 and M[SMK]["IRR"] < 1
assert not any(M[v]["cred"] for v in NOT_H)
assert not N["negctl"]["cpr_awareness_rate"]["cred"] and N["negctl"]["road_pavement_rate"]["cred"] and N["negctl"]["fires_per_10000"]["cred"]
assert all(N["mv"][v]["robust"] for v in ROB) and not N["mv"][POOL]["robust"] and not N["mv"][SPH]["robust"]
assert all(SC("sage", v)[3] for v in ROB) and all(S43("KH_typeI", v)[3] for v in ROB) and KHI < N["waic_main"] and KHI == min(N["s43_waic"][k] for k in KH)
assert not any(S43(a, v)[3] for a in ("KH_typeII", "KH_typeIV") for v in ROB) and KHII < N["waic_main"] and KHIV < N["waic_main"]
assert [(v, w) for v in ROB for w in WN if wt(v, w)[3]] == [(SCR, WN[2])]
assert all(S43(a, SPH)[3] and S43(a, SPH)[0] < 1 for a in KH[1:])
assert S41("C4_sido_year_iid", PSF)[3] and S41("C4_sido_year_iid", BL)[3] and not S41("C4_sido_year_iid", SCR)[3] and not S41("C4_sido_year_iid", SMK)[3]
assert BW(PSF, "within")[3] and BW(PSF, "within")[0] < 1 and BW(PSF, "between")[3] and BW(PSF, "between")[0] > 1
assert all(REG(PSF, r)[3] and REG(PSF, r)[0] < 1 for r in ("Capital", "Yeongnam", "Honam", "Chungcheong", "Gangwon_Jeju"))
assert BW(SCR, "between")[3] and BW(SCR, "within")[3] and NCO("GCA", SCR)[3] and NCO("ARTH", SCR)[3] and NCO("GCA", SCR)[0] > 1 and NCO("ARTH", SCR)[0] > 1
assert NCO("GCA", PSF)[3] and NCO("GCA", PSF)[0] > 1 and not NCO("ARTH", PSF)[3]
assert BW(BL, "within")[3] and not BW(BL, "between")[3] and not S43("KH_typeII", BL)[3] and not S43("KH_typeIV", BL)[3] and not any(wt(BL, w)[3] for w in WN)
assert sum(1 for r in ("Capital", "Yeongnam", "Honam", "Chungcheong", "Gangwon_Jeju") if REG(BL, r)[3] and REG(BL, r)[0] < 1) == 4
assert NCO("ARTH", BL)[3] and NCO("ARTH", BL)[0] > 1 and NCO("GCA", BL)[3] and NCO("GCA", BL)[0] > 1
assert not BW(SMK, "within")[3] and not BW(SMK, "between")[3] and not NCO("ARTH", SMK)[3] and not NCO("GCA", SMK)[3]
assert [r for r in ("Capital", "Yeongnam", "Honam", "Chungcheong", "Gangwon_Jeju") if REG(SMK, r)[3]] == ["Capital"]
assert REG(SCR, 'Honam')[3] and REG(SCR, 'Honam')[0] < 1 and S43('KH_typeIII', BL)[3] and S43('KH_typeIII', PSF)[3] and N['s43_waic']['KH_typeIII'] > N['waic_main'] and S43('KH_typeIII', POOL)[3] and S43('KH_typeIV', POOL)[3]
assert not N["covid_main"][3] and N["ppc"]["pit_ks_p"] < 0.001 and N["lat_rr"] < -0.5 and N["eb_tmp"] > 0.5
assert set(k for k in N["hot_by_sido"] if N["hot_by_sido"][k] >= 5) == {"전라남도", "경상남도", "전라북도", "충청남도", "광주시", "부산시"}

